import { Pool } from "pg";

const primary = new Pool({ connectionString: process.env.PRIMARY_URL });
const replica = new Pool({ connectionString: process.env.REPLICA_URL });

const RYW_WINDOW_MS = 5_000; // must be longer than your measured replica lag

type Session = { userId: string; lastWriteAt?: number }; // stored server-side or in a signed cookie

function poolForRead(s: Session) {
  const recentlyWrote = s.lastWriteAt !== undefined && Date.now() - s.lastWriteAt < RYW_WINDOW_MS;
  return recentlyWrote ? primary : replica; // read-your-writes for the author only
}

export async function updateName(s: Session, name: string) {
  const { rows } = await primary.query(
    "UPDATE users SET name = $1, version = version + 1 WHERE id = $2 RETURNING id, name, version",
    [name, s.userId],
  );
  s.lastWriteAt = Date.now();
  return rows[0]; // return the new state so the UI does not need to re-read
}

export async function getProfile(s: Session) {
  const { rows } = await poolForRead(s).query(
    "SELECT id, name, version FROM users WHERE id = $1",
    [s.userId],
  );
  return rows[0];
}

export async function withdraw(id: string, amount: number) {
  const { rows } = await replica.query(
    'SELECT balance FROM accounts WHERE id = $1', [id]);
  if (rows[0].balance < amount) throw new Error('insufficient funds');
  await primary.query(
    'UPDATE accounts SET balance = $1 WHERE id = $2',
    [rows[0].balance - amount, id]);
}

import { context, propagation } from '@opentelemetry/api';

// One shared client for every service-to-service call
export async function callService<T>(
  url: string,
  init: RequestInit & { deadline: number }, // absolute time (ms) the caller stops waiting
): Promise<T> {
  const { deadline, ...rest } = init;
  const remaining = deadline - Date.now();
  if (remaining <= 0) throw new Error('deadline exceeded before call'); // do not start useless work

  const headers: Record<string, string> = { 'content-type': 'application/json' };
  propagation.inject(context.active(), headers);       // adds W3C traceparent (once the OTel SDK is registered)
  headers['x-request-deadline'] = String(deadline);    // the callee can stop early too

  const res = await fetch(url, {
    ...rest,
    headers: { ...headers, ...(rest.headers as Record<string, string> | undefined) },
    signal: AbortSignal.timeout(Math.min(remaining, 2_000)), // never wait past the deadline
  });
  if (!res.ok) {
    await res.body?.cancel();                          // release the connection
    throw new Error(`${url} -> ${res.status}`);
  }
  return (await res.json()) as T;
}

