import {
  SQSClient, ReceiveMessageCommand, DeleteMessageCommand, ChangeMessageVisibilityCommand,
} from "@aws-sdk/client-sqs";

const sqs = new SQSClient({});
const QueueUrl = process.env.QUEUE_URL!;

export async function poll(handle: (body: unknown, messageId: string) => Promise<void>) {
  for (;;) {
    const { Messages = [] } = await sqs.send(new ReceiveMessageCommand({
      QueueUrl,
      MaxNumberOfMessages: 10,
      WaitTimeSeconds: 20,   // long polling: fewer empty (billed) receives
      VisibilityTimeout: 60, // longer than normal processing time
    }));

    await Promise.all(Messages.map(async (m) => {
      // heartbeat: keep the message hidden while a slow job is still running
      const hb = setInterval(() => {
        sqs.send(new ChangeMessageVisibilityCommand({
          QueueUrl, ReceiptHandle: m.ReceiptHandle!, VisibilityTimeout: 60,
        })).catch(() => {});
      }, 30_000);
      try {
        await handle(JSON.parse(m.Body!), m.MessageId!); // must be idempotent
        // ack = delete, only after the work is committed
        await sqs.send(new DeleteMessageCommand({ QueueUrl, ReceiptHandle: m.ReceiptHandle! }));
      } catch (err) {
        // no delete: redelivered later; after maxReceiveCount it moves to the DLQ
        console.error("job failed", m.MessageId, err);
      } finally {
        clearInterval(hb);
      }
    }));
  }
}

