type Ctx = { sagaId: string; orderId: string };
type Step = {
  name: string;
  run: (ctx: Ctx) => Promise<void>;         // idempotent: key = `${sagaId}:${name}`
  compensate?: (ctx: Ctx) => Promise<void>; // idempotent, and safe if run never happened
  forwardOnly?: boolean;                    // after the pivot: retry, never undo
};
type Status = 'RUNNING' | 'COMPENSATING' | 'COMPLETED' | 'FAILED_COMPENSATED' | 'NEEDS_HUMAN';
interface SagaStore {
  load(id: string): Promise<{ status: Status; started: string[]; done: string[] }>;
  markStarted(id: string, step: string): Promise<void>;
  markDone(id: string, step: string): Promise<void>;
  setStatus(id: string, status: Status, reason?: string): Promise<void>;
}
declare const reserveStock: Step['run'], releaseStock: Step['run'], chargeCard: Step['run'],
  refundCard: Step['run'], createShipment: Step['run'], sendEmail: Step['run'];
declare function retryUntilDone(fn: () => Promise<void>): Promise<void>; // backoff; throws after N tries

const steps: Step[] = [
  { name: 'reserveStock', run: reserveStock, compensate: releaseStock },
  { name: 'chargeCard', run: chargeCard, compensate: refundCard },
  { name: 'createShipment', run: createShipment },          // pivot: last step that may fail
  { name: 'sendEmail', run: sendEmail, forwardOnly: true }, // irreversible: last
];

export async function runSaga(ctx: Ctx, store: SagaStore) {
  const { status, started, done } = await store.load(ctx.sagaId); // resume after a crash
  if (status === 'COMPLETED' || status === 'FAILED_COMPENSATED' || status === 'NEEDS_HUMAN') return;
  if (status === 'COMPENSATING') return compensate(ctx, store, started);
  for (const step of steps) {
    if (done.includes(step.name)) continue;
    await store.markStarted(ctx.sagaId, step.name);
    if (!started.includes(step.name)) started.push(step.name);
    try {
      await (step.forwardOnly ? retryUntilDone(() => step.run(ctx)) : step.run(ctx));
    } catch (err) {
      if (step.forwardOnly) return store.setStatus(ctx.sagaId, 'NEEDS_HUMAN', String(err));
      await store.setStatus(ctx.sagaId, 'COMPENSATING', String(err)); // save the decision first
      return compensate(ctx, store, started);
    }
    await store.markDone(ctx.sagaId, step.name);
  }
  await store.setStatus(ctx.sagaId, 'COMPLETED');
}

async function compensate(ctx: Ctx, store: SagaStore, started: string[]) {
  for (const prev of [...steps].reverse()) {
    if (!started.includes(prev.name) || !prev.compensate) continue;
    try { await retryUntilDone(() => prev.compensate!(ctx)); }
    catch (err) { return store.setStatus(ctx.sagaId, 'NEEDS_HUMAN', String(err)); }
  }
  await store.setStatus(ctx.sagaId, 'FAILED_COMPENSATED');
}

