const RETRYABLE = new Set([408, 429, 500, 502, 503, 504]);
const sleep = (ms: number) => new Promise((r) => setTimeout(r, ms));

// Full jitter: wait a random time between 0 and min(cap, base * 2^attempt)
function backoff(attempt: number, baseMs: number, capMs: number) {
  return Math.random() * Math.min(capMs, baseMs * 2 ** attempt);
}

// Use only for requests that are safe to repeat (GET, PUT, or POST with an Idempotency-Key)
export async function fetchWithRetry(
  url: string,
  init: RequestInit = {},
  { attempts = 3, baseMs = 100, capMs = 2_000, timeoutMs = 1_000 } = {},
): Promise<Response> {
  for (let attempt = 1; ; attempt++) {
    const timeout = AbortSignal.timeout(timeoutMs);
    const signal = init.signal ? AbortSignal.any([init.signal, timeout]) : timeout;
    try {
      const res = await fetch(url, { ...init, signal });
      if (!RETRYABLE.has(res.status) || attempt >= attempts) return res;
      const retryAfterMs = Number(res.headers.get('retry-after')) * 1000; // 0 if absent, NaN if a date
      if (retryAfterMs > capMs) return res;  // server wants a long pause: let the caller decide
      await res.body?.cancel();              // free the connection before retrying
      await sleep(retryAfterMs > 0 ? retryAfterMs : backoff(attempt, baseMs, capMs));
    } catch (err) {
      // network error or TimeoutError; stop if the caller itself gave up
      if (init.signal?.aborted || attempt >= attempts) throw err;
      await sleep(backoff(attempt, baseMs, capMs));
    }
  }
}

