const RECS_URL = process.env.RECS_URL!;

// Optional dependency: short timeout, fallback value, never fails the page
async function optional<T>(call: (signal: AbortSignal) => Promise<T>, fallback: T, ms = 250): Promise<T> {
  try {
    return await call(AbortSignal.timeout(ms));
  } catch {
    return fallback; // also increment a metric, e.g. fallback_used_total{dep="recs"}
  }
}

export async function productPage(id: string) {
  // start the optional call first so it runs in parallel
  const recsP = optional(async (signal) => {
    const r = await fetch(`${RECS_URL}/for/${id}`, { signal });
    if (!r.ok) throw new Error(`recs ${r.status}`); // a 500 body is not a list of products
    return (await r.json()) as unknown[];
  }, []);
  // critical: if these fail, the request fails
  const [product, price] = await Promise.all([getProduct(id), getPrice(id)]);
  return { product, price, recs: await recsP };
}

// Load shedding: bounded concurrency and a fast 503, instead of a growing queue
let inFlight = 0;
const MAX_IN_FLIGHT = 200;

export function admit(res: ServerResponse): (() => void) | null {
  if (inFlight >= MAX_IN_FLIGHT) {
    res.writeHead(503, { 'Retry-After': '2' }).end();
    return null;
  }
  inFlight++;
  return () => { inFlight--; }; // call when the request finishes
}

