import { createHash } from "node:crypto";

function hash32(s: string): number {
  // first 4 bytes of MD5 as an unsigned 32-bit number (ketama-style)
  return createHash("md5").update(s).digest().readUInt32BE(0);
}

export class HashRing {
  private points: { h: number; node: string }[] = [];

  constructor(nodes: string[], private vnodes = 160) {
    for (const n of nodes) this.add(n);
  }

  add(node: string) {
    for (let i = 0; i < this.vnodes; i++) {
      this.points.push({ h: hash32(`${node}#${i}`), node });
    }
    this.points.sort((a, b) => a.h - b.h);
  }

  remove(node: string) {
    this.points = this.points.filter((p) => p.node !== node);
  }

  get(key: string): string {
    const h = hash32(key);
    let lo = 0, hi = this.points.length; // binary search: first point >= h
    while (lo < hi) {
      const mid = (lo + hi) >>> 1;
      if (this.points[mid].h < h) lo = mid + 1; else hi = mid;
    }
    return this.points[lo % this.points.length].node; // past the end: wrap to the start
  }
}

const nodes = ['cache-a', 'cache-b', 'cache-c', 'cache-d'];

export function nodeFor(key: string): string {
  return nodes[hash32(key) % nodes.length];
}

declare function hash32(s: string): number;

type Point = { h: number; node: string };

export function lookup(points: Point[], h: number): string {
  // points are sorted by h, ascending
  const p = points.find((p) => p.h >= h);
  return p!.node;
}

